SELECT '201.579.083-72' CPF ,'08/09/2026' DATA_OBITO FROM DUAL UNION ALL
SELECT '302.719.913-72' CPF ,'08/09/2026' DATA_OBITO FROM DUAL UNION ALL
SELECT '077.087.343-04' CPF ,'09/09/2026' DATA_OBITO FROM DUAL UNION ALL
SELECT '048.047.753-15' CPF ,'17/09/2026' DATA_OBITO FROM DUAL UNION ALL
SELECT '065.086.503-00' CPF ,'18/09/2026' DATA_OBITO FROM DUAL UNION ALL
SELECT '126.009.033-72' CPF ,'18/09/2026' DATA_OBITO FROM DUAL UNION ALL
SELECT '160.126.903-04' CPF ,'20/09/2026' DATA_OBITO FROM DUAL 
)
SELECT
    S.*
FROM
    (
    SELECT
        E.SIGLA ORGAO,
        FO.CHAVE_FOLHA,
        FF.ID_PENSIONISTA,
        FF.ID_FUNCIONARIO,
        FF.ID_FOLHA_FUNCIONARIO,
        PDC.CPF_PESSOA CPF,
        HN.NOME,
        CO.ID_CERTIDAO_OBITO,
        NVL(FF.MATR_DEPENDENTE, FF.COD_INSTITUCIONAL) MATRICULA,
        FF.IND_REMUNERACAO,
        PD.NOME_DIVISAO,
        PS.NOME_SITUACAO,
        TF.NOME_TIPO_FUNCIONARIO,
        'INSERT INTO SW_ADAPI.FUNC_DESLIGAMENTO (ID_DESLIGAMENTO, ID_FUNCIONARIO, DATA_CADASTRO, DATA_DESLIGAMENTO, ID_PERFIL, ID_SEFIP_MOVIMENTACAO,ID_ESOCIAL_MOTIVO_DESLIGAMENTO)VALUES (SW_ADAPI.SEQ_FUNC_DESLIGAMENTO.NEXTVAL,'|| FF.ID_FUNCIONARIO ||  ',''' || SYSDATE || ''',''30/09/2026'', '|| FP.ID_FUNCIONARIO_PERFIL ||', 1000024 ,45 ;' INSERT_1,
        'UPDATE SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT SET DATA_TERM_BENEFICIO = '''|| O.DATA_OBITO || ''';'UPDATE_1,
        'UPDATE SW_PUBLICO.PESSOA SET DATA_OBITO = ''' || O.DATA_OBITO || ''' WHERE ID_PESSOA = ' || PDC.ID_PESSOA || ';' UPDATE_2,
        'INSERT INTO SW_PUBLICO.PESSOA_CERTIDAO_OBITO (ID_CERTIDAO_OBITO, ID_PESSOA, DATA_OBITO, ID_ENTIDADE_EXTERNA, OFICIAL_TITULAR, DATA_CADASTRO) VALUES (SW_PUBLICO.SQ_PK_OBITO_PESSOA.NEXTVAL, ' || PDC.ID_PESSOA || ', ''' || O.DATA_OBITO || ''', 1003900, ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'', ''' || SYSDATE || ''');' INSERT_2,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'UPDATE SW_ADAPI.FOLHA_FUNC SET IND_REMUNERACAO = ''N'' WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END UPDATE_3,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_ADAPI.FOLHA_FUNC_RUBRICA WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_2,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_PUBLICO.FOLHA_BASE_UNICA_IMPOSTO WHERE ID_FOLHA = ' || FO.ID_FOLHA || ' AND ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ' AND ID_FUNCIONARIO = ' || FF.ID_FUNCIONARIO || ' AND ID_EMPRESA = ' || E.ID_EMPRESA || ';'
            ELSE 'FOLHA FECHADA'
        END DELETE_B,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN
                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL THEN 'UPDATE SW_ADAPI.FUNCIONARIO_PERFIL SET DATA_FIM = ''30/09/2026'' WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';'
                END
            ELSE 'FOLHA FECHADA'
        END UPDATE_4,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN
                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL  THEN 'INSERT INTO SW_ADAPI.FUNCIONARIO_PERFIL (ID_FUNCIONARIO_PERFIL, ID_FUNCIONARIO, ID_PERFIL, ID_MOVIMENTACAO, ID_TIPO_FUNCIONARIO, ID_ESB_CATEG_TRABALHADOR, ID_TIPO_INCIDENCIA, IND_PERMITE_ALTERAR, ID_REMUNERACAO, DATA_CADASTRO, DATA_INICIO, OBSERVACAO) VALUES (SW_ADAPI.SQ_PK_FUNCIONARIO_PERFIL.NEXTVAL, ' || FF.ID_FUNCIONARIO || ', ' || (SELECT ID_PERFIL FROM SW_ADAPI.RHB_PERFIL WHERE ID_DIVISAO = PD.ID_DIVISAO AND ID_SITUACAO = 1000001) || ', 8, ' || FP.ID_TIPO_FUNCIONARIO || ', ' || NVL(TO_CHAR(FP.ID_ESB_CATEG_TRABALHADOR), 'NULL') || ', ' || FP.ID_TIPO_INCIDENCIA || ', ''' || FP.IND_PERMITE_ALTERAR || ''', 2, ''' || SYSDATE || ''', ''01/10/2026'', ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'');'
                END
            ELSE 'FOLHA FECHADA'
        END INSERT_3,
        CASE
            WHEN PC.ID_PENSIONISTA IS NOT NULL THEN 'UPDATE SW_ADAPI.FUNC_PENSAO_CIVIL SET DATA_FIM = '|| O.DATA_OBITO || ' WHERE ID_PENSIONISTA = ' || PC.ID_PENSIONISTA || ';'
        END UP_PEN
    FROM
        SW_ADAPI.FOLHA FO
        JOIN SW_ADAPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PDC.DATA_BAIXA IS NULL
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND HN.DATA_FIM IS NULL
        LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPP ON PPP.ID_PESSOA =  NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PPP.ID_FUNCIONARIO_PAGAMENTO = FF.ID_FUNCIONARIO
        LEFT JOIN SW_PUBLICO.PESSOA_CERTIDAO_OBITO CO ON CO.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
        LEFT JOIN SW_ADAPI.FUNC_PENSAO_CIVIL PC ON PC.ID_PENSIONISTA = FF.ID_PENSIONISTA AND PC.DATA_FIM IS NULL
        LEFT JOIN SW_ADAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        LEFT JOIN SW_ADAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO TF ON TF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
        JOIN OBITOS O ON O.CPF = PDC.CPF_PESSOA
        JOIN SW_PUBLICO.EMPRESA E ON E.SIGLA = 'SW_ADAPI'
    WHERE
        FO.MES = 10
        AND FO.ANO = 2026
        AND PDC.CPF_PESSOA IN ('217.209.243-68','069.230.203-44','097.107.873-49','077.571.233-72','065.502.823-49','066.972.753-91','048.281.353-91','066.511.943-72','182.109.703-30','132.080.803-44','337.462.903-25','150.654.133-04','341.501.883-00','053.576.593-20','150.412.803-63','043.715.773-34','053.551.093-49','096.621.623-72','199.875.793-53','066.976.233-49','159.639.343-20','200.428.843-49','062.930.003-82','152.619.213-68','186.102.503-34','201.579.083-72','302.719.913-72','077.087.343-04','048.047.753-15','065.086.503-00','126.009.033-72','160.126.903-04')
        AND FF.IND_REMUNERACAO = 'S'

UNION ALL

SELECT
