            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'DELETE FROM SW_AGESPISA.FOLHA_FUNC_RUBRICA WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
