            ELSE 'FOLHA FECHADA'
        END DELETE_B,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN
                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL THEN 'UPDATE SW_AGESPISA.FUNCIONARIO_PERFIL SET DATA_FIM = ''30/09/2026'' WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';'
                END
            ELSE 'FOLHA FECHADA'
        END UPDATE_4,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN
                CASE
                    WHEN PC.ID_PENSIONISTA IS NULL  THEN 'INSERT INTO SW_AGESPISA.FUNCIONARIO_PERFIL (ID_FUNCIONARIO_PERFIL, ID_FUNCIONARIO, ID_PERFIL, ID_MOVIMENTACAO, ID_TIPO_FUNCIONARIO, ID_ESB_CATEG_TRABALHADOR, ID_TIPO_INCIDENCIA, IND_PERMITE_ALTERAR, ID_REMUNERACAO, DATA_CADASTRO, DATA_INICIO, OBSERVACAO) VALUES (SW_AGESPISA.SQ_PK_FUNCIONARIO_PERFIL.NEXTVAL, ' || FF.ID_FUNCIONARIO || ', ' || (SELECT ID_PERFIL FROM SW_AGESPISA.RHB_PERFIL WHERE ID_DIVISAO = PD.ID_DIVISAO AND ID_SITUACAO = 1000001) || ', 8, ' || FP.ID_TIPO_FUNCIONARIO || ', ' || NVL(TO_CHAR(FP.ID_ESB_CATEG_TRABALHADOR), 'NULL') || ', ' || FP.ID_TIPO_INCIDENCIA || ', ''' || FP.IND_PERMITE_ALTERAR || ''', 2, ''' || SYSDATE || ''', ''01/10/2026'', ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'');'
                END
            ELSE 'FOLHA FECHADA'
        END INSERT_3,
        CASE
            WHEN PC.ID_PENSIONISTA IS NOT NULL THEN 'UPDATE SW_AGESPISA.FUNC_PENSAO_CIVIL SET DATA_FIM = '|| O.DATA_OBITO || ' WHERE ID_PENSIONISTA = ' || PC.ID_PENSIONISTA || ';'
        END UP_PEN
    FROM
        SW_AGESPISA.FOLHA FO
        JOIN SW_AGESPISA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PDC.DATA_BAIXA IS NULL
