        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PDC.DATA_BAIXA IS NULL
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND HN.DATA_FIM IS NULL
        LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPP ON PPP.ID_PESSOA =  NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PPP.ID_FUNCIONARIO_PAGAMENTO = FF.ID_FUNCIONARIO
        LEFT JOIN SW_PUBLICO.PESSOA_CERTIDAO_OBITO CO ON CO.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
