        FF.IND_REMUNERACAO,
        PD.NOME_DIVISAO,
        PS.NOME_SITUACAO,
        TF.NOME_TIPO_FUNCIONARIO,
        'INSERT INTO SW_TVANTARES.FUNC_DESLIGAMENTO (ID_DESLIGAMENTO, ID_FUNCIONARIO, DATA_CADASTRO, DATA_DESLIGAMENTO, ID_PERFIL, ID_SEFIP_MOVIMENTACAO,ID_ESOCIAL_MOTIVO_DESLIGAMENTO)VALUES (SW_TVANTARES.SEQ_FUNC_DESLIGAMENTO.NEXTVAL,'|| FF.ID_FUNCIONARIO ||  ',''' || SYSDATE || ''',''30/09/2026'', '|| FP.ID_FUNCIONARIO_PERFIL ||', 1000024 ,45 ;' INSERT_1,
        'UPDATE SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT SET DATA_TERM_BENEFICIO = '''|| O.DATA_OBITO || ''';'UPDATE_1,
        'UPDATE SW_PUBLICO.PESSOA SET DATA_OBITO = ''' || O.DATA_OBITO || ''' WHERE ID_PESSOA = ' || PDC.ID_PESSOA || ';' UPDATE_2,
        'INSERT INTO SW_PUBLICO.PESSOA_CERTIDAO_OBITO (ID_CERTIDAO_OBITO, ID_PESSOA, DATA_OBITO, ID_ENTIDADE_EXTERNA, OFICIAL_TITULAR, DATA_CADASTRO) VALUES (SW_PUBLICO.SQ_PK_OBITO_PESSOA.NEXTVAL, ' || PDC.ID_PESSOA || ', ''' || O.DATA_OBITO || ''', 1003900, ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'', ''' || SYSDATE || ''');' INSERT_2,
        CASE
            WHEN FO.DATA_FECHAMENTO IS NULL THEN 'UPDATE SW_TVANTARES.FOLHA_FUNC SET IND_REMUNERACAO = ''N'' WHERE ID_FOLHA_FUNCIONARIO = ' || FF.ID_FOLHA_FUNCIONARIO || ';'
            ELSE 'FOLHA FECHADA'
