                    WHEN PC.ID_PENSIONISTA IS NULL  THEN 'INSERT INTO SW_TVANTARES.FUNCIONARIO_PERFIL (ID_FUNCIONARIO_PERFIL, ID_FUNCIONARIO, ID_PERFIL, ID_MOVIMENTACAO, ID_TIPO_FUNCIONARIO, ID_ESB_CATEG_TRABALHADOR, ID_TIPO_INCIDENCIA, IND_PERMITE_ALTERAR, ID_REMUNERACAO, DATA_CADASTRO, DATA_INICIO, OBSERVACAO) VALUES (SW_TVANTARES.SQ_PK_FUNCIONARIO_PERFIL.NEXTVAL, ' || FF.ID_FUNCIONARIO || ', ' || (SELECT ID_PERFIL FROM SW_TVANTARES.RHB_PERFIL WHERE ID_DIVISAO = PD.ID_DIVISAO AND ID_SITUACAO = 1000001) || ', 8, ' || FP.ID_TIPO_FUNCIONARIO || ', ' || NVL(TO_CHAR(FP.ID_ESB_CATEG_TRABALHADOR), 'NULL') || ', ' || FP.ID_TIPO_INCIDENCIA || ', ''' || FP.IND_PERMITE_ALTERAR || ''', 2, ''' || SYSDATE || ''', ''01/10/2026'', ''DATA ÓBITO EXTRAÍDA DA API DATAPREV'');'
                END
            ELSE 'FOLHA FECHADA'
        END INSERT_3,
        CASE
            WHEN PC.ID_PENSIONISTA IS NOT NULL THEN 'UPDATE SW_TVANTARES.FUNC_PENSAO_CIVIL SET DATA_FIM = '|| O.DATA_OBITO || ' WHERE ID_PENSIONISTA = ' || PC.ID_PENSIONISTA || ';'
        END UP_PEN
    FROM
        SW_TVANTARES.FOLHA FO
        JOIN SW_TVANTARES.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PDC.DATA_BAIXA IS NULL
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND HN.DATA_FIM IS NULL
        LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPP ON PPP.ID_PESSOA =  NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PPP.ID_FUNCIONARIO_PAGAMENTO = FF.ID_FUNCIONARIO
        LEFT JOIN SW_PUBLICO.PESSOA_CERTIDAO_OBITO CO ON CO.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
        LEFT JOIN SW_TVANTARES.FUNC_PENSAO_CIVIL PC ON PC.ID_PENSIONISTA = FF.ID_PENSIONISTA AND PC.DATA_FIM IS NULL
        LEFT JOIN SW_TVANTARES.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        LEFT JOIN SW_TVANTARES.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO TF ON TF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
        JOIN OBITOS O ON O.CPF = PDC.CPF_PESSOA
        JOIN SW_PUBLICO.EMPRESA E ON E.SIGLA = 'SW_TVANTARES'
    WHERE
        FO.MES = 10
